from collections import Counter

def solve(g):
    h,w=len(g),len(g[0])
    cnt=Counter(v for row in g for v in row)
    bg=cnt.most_common(1)[0][0]
    nonbg={v:p for v,p in cnt.items() if v!=bg}
    marks=[(i,j) for i in range(h) for j in range(w) if g[i][j]!=bg]
    # group by color
    byc={}
    for i,j in marks: byc.setdefault(g[i][j],[]).append((i,j))
    out=[row[:] for row in g]
    def bounce(i,j,di,dj,m):
        n=0
        while True:
            ni,nj=i+di,j+dj
            if not(0<=ni<h and 0<=nj<w) or out[ni][nj]!=bg:
                if out[ni][nj]==m: return
                # reflect about horizontal -> flip dj
                di,dj=dj,-di
                ni,nj=i+di,j+dj
                if not(0<=ni<h and 0<=nj<w) or out[ni][nj]!=bg or out[ni][nj]==m:
                    return
            else:
                out[ni][nj]=3
                i,j=ni,nj
    for c,pts in byc.items():
        pts=set(pts)
        # try both diagonal directions from each marker; run ball from each marker
        for (i0,j0) in pts:
            for d1,d2 in [(-1,-1),(-1,1),(1,-1),(1,1)]:
                i,j,di,dj=i0,j0,d1,d2
                while True:
                    ni,nj=i+di,j+dj
                    if not(0<=ni<h and 0<=nj<w) or out[ni][nj]!=bg:
                        if out[ni][nj] in pts: break
                        di,dj=dj,-di
                        ni,nj=i+di,j+dj
                        if not(0<=ni<h and 0<=nj<w) or out[ni][nj]!=bg or out[ni][nj] in pts: break
                    else:
                        out[ni][nj]=3
                        i,j=ni,nj
    return out

