def sim(gi, term, emit_opts=('both','firstend'), maxb=30):
    """cell-based billiard ray(s) from stroke endpoint(s) along stroke axis"""
    cnt=Counter(x for r in gi for x in r); bgi=cnt.most_common(1)[0][0]
    H,W=len(gi),len(gi[0])
    objs={}
    seen=set()
    for i in range(H):
        for j in range(W):
            if gi[i][j]!=bgi and (i,j) not in seen:
                col=gi[i][j]; q=[(i,j)];seen.add((i,j));cs=[]
                while q:
                    x,y=q.pop();cs.append((x,y))
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            a,b=x+dx,y+dy
                            if 0<=a<H and 0<=b<W and (a,b) not in seen and gi[a][b]==col:
                                seen.add((a,b));q.append((a,b))
                objs.setdefault(col,set()).update(cs)
    strok=[c for c,s in objs.items() if len(s)==min(len(objs[c]) for col,sc in objs.items()) for c in list(s)] 
    # find the smallest object(s) as stroke
    m=min(len(s) for s in objs.values())
    strokes=list(objs[k] for k,s in objs.items() if len(s)==m)
    res=set()
    for s in strokes:
        for start,sdir in [(s[0],tuple(map(copysign,[1],[0,0])))]: pass
        rs=[p[0] for p in s];cc=[p[1] for p in s]
        dirs=set()
        # compute dominant step sign
        d=(math.copysign(1,max(rs)-min(rs)),math.copysign(1,max(cc)-min(cc))) if (max(rs)-min(rs),max(cc)-min(cc))!=(0,0) else None
        if d is None: continue
        # endpoints
        ends=[(min(rs),min(cc)),(max(rs),max(cc))]
        if emit_opts=='both': emits={e:-d for e in ends}
        elif emit_opts=='firstend': emits={(s[0]):-d,(s[-1]):d}
        else: emits=dict.fromkeys([(e,k) for e in ends for k in [d,-d]])
        for e,dv in emits.items():
            pos,epr=e
            dr,dc=dv
            r,c=pos; steps=0
            while steps<maxb:
                nr,nc=r+dr,c+dc
                if not(0<=nr<H and 0<=nc<W): break
                if gi[nr][nc]!=bgi:
                    # reflect: determine flip
                    if emit_opts==term or True:
                        pass
                    # try flipping vertical then horizontal, pick whichever lands in background later
                    cands={}
                    for dr2,dc2 in [(dr,-dc),(-dr,dc)]:
                        # simulate short run to see how far
                        rr,cc2=r,c; dist=0
                        while True:
                            nr2,nc2=rr+dr2,cc2+dc2
                            if not(0<=nr2<H and 0<=nc2<W) or gi[nr2][nc2]!=bgi: break
                            dist+=1;rr,cc2=nr2,nc2
                        cands[(dist,dr2,dc2)]=dist
                        dist=0
                    best=max(cands,key=cands.get)
                    dr,dc=best[1],best[2]
                else:
                    res.add((nr,nc))
                r,c=nr,nc; steps+=1
    return res
