import math
from collections import Counter as C2, deque

def solve(g):
    R=len(g); C=len(g[0])
    bg=C2(x for row in g for x in row).most_common(1)[0][0]
    objs=comps(g,bg)
    m=min(objs,key=len)
    S=set(m); Ob={(r,c) for o in [o for o in objs if o not in (m,)] for r,c in o}
    out=[row[:] for row in g]
    pts=sorted(m)
    d0,d1=pts[0],pts[-1]
    dy,dx=d1[0]-d0[0], d1[1]-d0[1]
    gg=max(1,math.gcd(abs(dy),abs(dx)))
    u=(dy//gg,dx//gg)
    def shoot(start,d):
        p=start; cells=[]
        while True:
            q=(p[0]+d[0],p[1]+d[1])
            if not(0<=q[0]<R and 0<=q[1]<C): break
            if q in S: break
            if q in Ob or g[q[0]][q[1]]!=bg:
                cand=[]
                for nd in [(-d[0],d[1]),(d[0],-d[1])]:
                    qq=(p[0]+nd[0],p[1]+nd[1])
                    if 0<=qq[0]<R and 0<=qq[1]<C and qq not in S and qq not in Ob and g[qq[0]][qq[1]]==bg:
                        cand.append(nd)
                if not cand: return cells
                d=cand[0]; continue
            if g[q[0]][q[1]]==bg:
                cells.append(q); p=q
        return cells
    res=[]
    for sgn in (1,-1):
        for start in m:
            res+=shoot(start,u*sgn)
    for r,c in res:
        if (r,c) not in S: out[r][c]=3
    return out
for k,(gi,go) in demos.items():
