import math
def solve_axis(g):
    R,C=len(g),len(g[0])
    bg=C2(x for row in g for x in row).most_common(1)[0][0]
    objs=comps(g,bg)
    def span(o): return max(p[0] for p in o)-min(p[0] for p in o),max(p[1] for p in o)-min(p[1] for p in o)
    stroke=max(objs,key=lambda o:(span(o)[0]+span(o)[1]))
    S=set(stroke); Ob={(r,c) for o in objs if o!=stroke for r,c in o}
    out=[row[:] for row in g]; res=set()
    pts=sorted(S); a,b=pts[0],pts[-1]
    dy,dx=b[0]-a[0],b[1]-a[1]
    gg=max(1,math.gcd(abs(dy),abs(dx))); u=(dy//gg,dx//gg)
    def shoot(start,d):
        p=list(start); cells=[]
        while True:
            q=(p[0]+d[0],p[1]+d[1])
            if not(0<=q[0]<R and 0<=q[1]<C): break
            if q in S: break
            if q in Ob:
                cand=[nd for nd in [(-d[0],d[1]),(d[0],-d[1])]
                      if 0<=p[0]+nd[0]<R and 0<=p[1]+nd[1]<C
                      and (p[0]+nd[0],p[1]+nd[1]) not in S and (p[0]+nd[0],p[1]+nd[1]) not in Ob
                      and g[p[0]+nd[0]][p[1]+nd[1]]==bg]
                if not cand: break
                d=cand[0]; continue
            if g[q[0]][q[1]]==bg:
                cells.append(q); p=q
        return cells
    for sgn in (1,-1):
        for st in stroke:
            res|=set(shoot(st,(u[0]*sgn,u[1]*sgn)))
    for r,c in res:
        if (r,c) not in S: out[r][c]=3
    return out
